// QueryVoteCategory queries the vote_category edge of a VoteResult.
func (c *VoteResultClient) QueryVoteCategory(_m *VoteResult) *VoteCategoryQuery {
	query := (&VoteCategoryClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(voteresult.Table, voteresult.FieldID, id),
			sqlgraph.To(votecategory.Table, votecategory.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, voteresult.VoteCategoryTable, voteresult.VoteCategoryColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

