type (
	hooks struct {
		Answer, Hackathon, HackathonState, Page, Participant, Phase, Project, Question,
		Submission, Team, TeamParticipant, Track, User, Vote, VoteCategory,
		VoteResult []ent.Hook
	}
	inters struct {
		Answer, Hackathon, HackathonState, Page, Participant, Phase, Project, Question,
		Submission, Team, TeamParticipant, Track, User, Vote, VoteCategory,
		VoteResult []ent.Interceptor
	}
)
